% Electric Field Intensity of a Charged Ring
% Given constants
lambda = 1.7e-7;        % charge density in C/m
epsilon0 = 8.85e-12;    % electric constant in F/m
R = 0.06;               % radius = 6 cm converted to meters

% Part (i): E at z = 0, 2, 4, 6, 8, 10 cm
z1 = [0, 2, 4, 6, 8, 10] * 1e-2;  % convert cm to m

% Calculate E using the formula
E1 = (lambda .* R .* z1) ./ (2 .* epsilon0 .* (z1.^2 + R^2).^(3/2));

% Display results
disp('Part (i): E at specified z values');
disp('z (cm)   E (N/C)');
for i = 1:length(z1)
    fprintf('z = %4.0f cm,  E = %.4e N/C\n', z1(i)*100, E1(i));
end

% Part (ii): Find z where E is maximum
z2 = (2:0.01:6) * 1e-2;   % z from 2 cm to 6 cm, step 0.01 cm, in meters

% Calculate E for all z values
E2 = (lambda .* R .* z2) ./ (2 .* epsilon0 .* (z2.^2 + R^2).^(3/2));

% Find maximum E and corresponding z
[E_max, idx] = max(E2);            % max value and its index
z_at_max = z2(idx);                % z value at maximum

% Display result
fprintf('\nPart (ii): Maximum E = %.4e N/C at z = %.2f cm\n', E_max, z_at_max*100);

% Optional: plot E vs z for Part (ii)
plot(z2*100, E2);
xlabel('z (cm)');
ylabel('E (N/C)');
title('Electric Field Along Ring Axis');
grid on;

% Stress Intensity Factor Calculation
% Given values
b = 4;          % plate half-width in inches
a = 1.5;        % crack length in inches
sigma = 12000;  % applied stress in psi

% Calculate ratio a/b
ratio = a / b;  % = 0.375

% Numerator of the bracket
numerator = 1 - a/(2*b) + 0.326*(ratio)^2;

% Denominator of the bracket
denominator = sqrt(1 - ratio);

% Bracket term
bracket = numerator / denominator;

% sqrt(pi * a) term
sqrt_term = sqrt(pi * a);

% Final stress intensity factor k
k = sigma * sqrt_term * bracket;

% Display result
fprintf('Stress Intensity Factor k = %.2f psi*sqrt(in)\n', k);

% Create row vector with 5 zeros followed by 4.7
a = [zeros(1,5), 4.7];

% Verify the result
