% Solve Linear System: 4x-2y+6z=8, 2x+8y+2z=4, 6x+10y+3z=0

% Coefficient matrix
A = [4, -2, 6;
     2,  8, 2;
     6, 10, 3];

% Right-hand side vector
b = [8; 4; 0];

% Augmented matrix [A|b]
Aug = [A, b];

% Check consistency using rank
rankA = rank(A);
rankAug = rank(Aug);
n = size(A, 2);  % number of unknowns = 3

fprintf('rank(A) = %d\n', rankA);
fprintf('rank([A|b]) = %d\n', rankAug);

if rankA == rankAug
    if rankA == n
        fprintf('System is consistent with a UNIQUE solution.\n');
        % Solve using backslash operator
        sol = A \ b;
        fprintf('Solution: x = %.4f, y = %.4f, z = %.4f\n', sol(1), sol(2), sol(3));
    else
        fprintf('System is consistent with INFINITE solutions.\n');
    end
else
    fprintf('System is INCONSISTENT — no solution exists.\n');
