% Polynomial Curve Fitting
% Given data
x = [1, 2.2, 3.7, 6.4, 7.2, 9.2, 14.2, 17.8, 20.5, 23.2];
y = [12, 9, 6.6, 9, 11.5, 8.5, 5.5, 9.6, 6.5, 2.2];

% Fine x-axis for smooth curve plotting
x_fine = linspace(min(x), max(x), 200);

% Polynomial orders to fit
orders = [1, 2, 3, 5];
order_names = {'1st Order', '2nd Order', '3rd Order', '5th Order'};

figure;  % open a new figure

for k = 1:4
    n = orders(k);                         % polynomial order
    p = polyfit(x, y, n);                  % fit polynomial
    y_fit = polyval(p, x_fine);            % evaluate on fine grid

    subplot(2, 2, k);                      % 2x2 grid of subplots
    plot(x, y, 'ro', 'MarkerSize', 8);     % original data points (red circles)
    hold on;
    plot(x_fine, y_fit, 'b-');             % fitted polynomial (blue line)
    hold off;
    xlabel('x');
    ylabel('y');
    title(order_names{k});
    legend('Data', 'Fit');
    grid on;
end

% Factorial function definition
% Save this as fact.m
function y = fact(x)
  % Validate input: check for negative or non-integer
  if x < 0
    error('Error: Input must be non-negative. Received: %g', x);
  elseif floor(x) ~= x
    error('Error: Input must be an integer. Received: %g', x);
  end

  % Base case: 0! = 1
  if x == 0
    y = 1;
    return;
  end

  % Calculate factorial using a loop
  y = 1;
  for i = 1:x
    y = y * i;  % multiply current result by i
  end
endfunction

% --- Test the function ---

% (i) 9!
result1 = fact(9);
fprintf('9! = %d\n', result1);  % Expected: 362880

% (ii) 8.5! — should display error
try
  result2 = fact(8.5);
catch e
  fprintf('8.5!: %s\n', e.message);
end

% (iii) 0!
result3 = fact(0);
fprintf('0! = %d\n', result3);  % Expected: 1

% (iv) -5! — should display error
try
  result4 = fact(-5);
catch e
  fprintf('-5!: %s\n', e.message);
end

