def fact(x):
    # Validate input
    if x < 0:
        raise ValueError(f'Error: Input must be non-negative. Received: {x}')
    if int(x) != x:
        raise ValueError(f'Error: Input must be an integer. Received: {x}')

    # Base case
    if x == 0:
        return 1

    # Compute factorial using loop
    result = 1
    for i in range(1, int(x) + 1):
        result *= i  # multiply by each integer
    return result

# Test cases
print(f'9! = {fact(9)}')         # Expected: 362880

try:
    print(fact(8.5))             # Should raise error
except ValueError as e:
    print(f'8.5!: {e}')

print(f'0! = {fact(0)}')         # Expected: 1

try:
    print(fact(-5))              # Should raise error
except ValueError as e:
    print(f'-5!: {e}')

import math

x = int(input('Enter a number: '))

if x <= 1:
    print(f'{x} is NOT prime.')
else:
    is_prime = True  # assume prime

    # Check divisors from 2 to sqrt(x)
    for i in range(2, int(math.sqrt(x)) + 1):
        if x % i == 0:    # divisible — not prime
            is_prime = False
            break

    if is_prime:
        print(f'{x} IS prime.')
    else:
        print(f'{x} is NOT prime.')

