% Loan Balance Calculation
% Given values
A = 20000;      % loan amount in dollars
P = 391.32;     % monthly payment
r = 6.5;        % yearly interest rate (%)

% Monthly interest factor
q = 1 + r/1200;

% Payment intervals: every 6 months from 6 to 60
n_values = 6:6:60;

% Print table header
fprintf('%-10s %-15s %-20s\n', 'Month n', 'Balance B ($)', 'Percent Paid (%)');
fprintf('%s\n', repmat('-', 1, 47));

for n = n_values
    % Calculate balance using formula
    B = A * q^n - P * (q^n - 1) / (r/1200);

    % Calculate percentage of loan already paid
    pct_paid = (1 - B/A) * 100;

    % Print each row
    fprintf('%-10d %-15.2f %-20.2f\n', n, B, pct_paid);
end

